// ─── File: CondAggDemo.java ───
// Conditional aggregation: per-status counts and both-completed-and-cancelled.
package com.bank.condagg;

import java.util.*;
import java.util.logging.*;

public class CondAggDemo {
    private static final Logger log = Logger.getLogger(CondAggDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrderRepository repo = new OrderRepository();
        OrderPatternService service = new OrderPatternService(repo);

        log.info("=== Conditional aggregation: status counts per customer (one pass) ===");
        service.statusCountsPerCustomer().forEach((cust, c) ->
            log.info(() -> cust + " completed=" + c.completed
                + " cancelled=" + c.cancelled + " pending=" + c.pending));

        log.info("=== Customers with BOTH completed AND cancelled (HAVING) ===");
        service.customersWithBothCompletedAndCancelled()
            .forEach(id -> log.warning("pattern match: " + id));
    }
}

// ─── Would be in model/Order.java ───
class Order {
    final String orderId, customerId, status;
    Order(String id, String cust, String status) {
        this.orderId = id; this.customerId = cust; this.status = status;
    }
}

// ─── Would be in model/StatusCounts.java ───
class StatusCounts {
    int completed, cancelled, pending;
}

// ─── Would be in repository/OrderRepository.java ───
class OrderRepository {
    List<Order> findAll() {
        return List.of(
            new Order("O1", "C1", "COMPLETED"),
            new Order("O2", "C1", "CANCELLED"),
            new Order("O3", "C1", "PENDING"),
            new Order("O4", "C2", "COMPLETED"),
            new Order("O5", "C2", "COMPLETED"),
            new Order("O6", "C3", "CANCELLED"));
    }
}

// ─── Would be in service/OrderPatternService.java ───
class OrderPatternService {
    private final OrderRepository repo;
    OrderPatternService(OrderRepository repo) { this.repo = repo; }

    // One grouped pass: SUM(CASE WHEN status=... THEN 1 ELSE 0 END) per status.
    Map<String, StatusCounts> statusCountsPerCustomer() {
        Map<String, StatusCounts> map = new LinkedHashMap<>();
        for (Order o : repo.findAll()) {
            StatusCounts c = map.computeIfAbsent(o.customerId, k -> new StatusCounts());
            switch (o.status) {                        // the CASE WHEN branches
                case "COMPLETED" -> c.completed++;
                case "CANCELLED" -> c.cancelled++;
                case "PENDING"   -> c.pending++;
                default -> { }
            }
        }
        return map;
    }

    // HAVING both counters > 0 — single pass, no self-join needed.
    List<String> customersWithBothCompletedAndCancelled() {
        List<String> out = new ArrayList<>();
        statusCountsPerCustomer().forEach((cust, c) -> {
            if (c.completed > 0 && c.cancelled > 0) out.add(cust);
        });
        return out;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
